// PRIMARY: ethereum/spec/src/main/java/tech/pegasys/teku/spec/datastructures/execution/versions/electra/ExecutionRequestsDataCodec.java (lines 24-127)
// Implements EIP-7685 encoding/decoding of execution requests
// Note: teku (CL) does NOT compute requests_hash (double-SHA256) itself;
// it encodes requests and sends to EL via engine_newPayload for EL-side validation
public List<Bytes> encode(final ExecutionRequests executionRequests) {
  final List<Bytes> executionRequestsData = new ArrayList<>();
  final List<DepositRequest> deposits = executionRequests.getDeposits();
  if (!deposits.isEmpty()) {
    final Bytes depositRequestsData = executionRequestsSchema
        .getDepositRequestsSchema().createFromElements(deposits).sszSerialize();
    executionRequestsData.add(Bytes.concatenate(DepositRequest.REQUEST_TYPE_PREFIX, depositRequestsData));
  }
  // ... similar for withdrawals and consolidations
  return executionRequestsData;
}

